import{_ as n,l as m,o as e,c as l,v as r,p as i,x as t,d as p,i as h,S as s}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"垄断与勒纳指数","description":"","frontmatter":{"title":"垄断与勒纳指数","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/monopoly-lerner.md","filePath":"econ/monopoly-lerner.md","lastUpdated":1789023840000}'),d={name:"econ/monopoly-lerner.md"};function c(M,a,C,E,A,P){const o=m("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="垄断与勒纳指数" tabindex="-1">垄断与勒纳指数 <a class="header-anchor" href="#垄断与勒纳指数" aria-label="Permalink to &quot;垄断与勒纳指数&quot;">​</a></h1><div class="epigraph"><p>垄断势力等于价格超出边际成本的比例，而这一比例就是需求弹性的倒数。</p><footer>—— 据 Lerner, The Concept of Monopoly and the Measurement of Monopoly Power, Review of Economic Studies, 1934 整理</footer></div><p><a href="/econ/contestable-markets">上一课</a>（可竞争市场）。在价格接受与自由进入下把 \\(p\\) 钉在 \\(\\min\\mathrm{AC}\\)。本课不重讲行业供给加总。缺口是：若只有一家卖者、进入被挡住，厂商面对的是整条市场需求 \\(P(Q)\\)，不再是参数 \\(p\\)。\\(p=\\mathrm{MC}\\) 必须改写成带边际收入的一阶条件，并给出可观测的势力测度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>价格接受者的一阶条件是 \\(p=\\mathrm{MC}(q)\\)。垄断者多卖一单位，不仅那一单位按新价格卖，还把已经在卖的数量一起压价。边际收入 \\(\\mathrm{MR}(q)=P(q)+q P&#39;(q)\\)，最优是 \\(\\mathrm{MR}=\\mathrm{MC}\\)。缺口不是再画 AC，而是把偏离竞争基准的程度写成</p> \\[L=\\frac{P-\\mathrm{MC}}{P}=\\frac{1}{|\\varepsilon(q)|}, \\]<p>其中 \\(\\varepsilon\\) 是需求价格弹性。这就是勒纳指数。弹性无穷（水平需求）时 \\(L=0\\)，回到上一课的接受价格。弹性越接近 \\(1^+\\)，\\(L\\) 越大； \\(|\\varepsilon|\\le 1\\) 时 MR 非正，有正 MC 的垄断者不会停在那里。</p><p>产量低于竞争产量（竞争产量由 \\(P=\\mathrm{MC}\\) 读出），形成哈伯格三角形那块无谓损失。本课只钉这一局部比较；一般均衡的福利定理是后课程对象，不要在这里用效用可能性边界重写一遍。</p><h3 id="勒纳测度的是加价-不是利润率" tabindex="-1">勒纳测度的是加价，不是利润率 <a class="header-anchor" href="#勒纳测度的是加价-不是利润率" aria-label="Permalink to &quot;勒纳测度的是加价，不是利润率&quot;">​</a></h3><p>\\(L\\) 用的是 MC，不是 AC。正的勒纳可以和零经济利润共存——例如被进入威胁压在 AC 上但仍有 \\(P\\gt \\mathrm{MC}\\) 的容量约束情形，后课会碰到。反过来，短期沉没造成的会计亏损也不否定 \\(L\\gt 0\\)。不要把勒纳读成「赚钱多少」；上一课刚把零利润定义为进入条件，本课的势力是价格–边际成本缝。</p><p><span class="marginnote">Cournot 1838 已经对单一矿主写出 \\(\\mathrm{MR}=\\mathrm{MC}\\)。Lerner 的贡献是把加价与弹性连成可比较的指数。引用时不要把 1934 年的指数写成古诺寡占的 \\(n\\) 家公式——那是后课 \\(L_i=s_i/|\\varepsilon|\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定 \\(P(q)\\) 与<a href="/econ/cost-minimization">成本</a>侧的 \\(c(q)\\)（要素价格冻住），解 \\(\\mathrm{MR}(q)=\\mathrm{MC}(q)\\)，再读 \\(P(q)\\)。线性需求加常数 MC 时，垄断产量是竞争产量的一半——这是教具，不是一般定理。弹性随点变，故 \\(L\\) 随均衡点变，不是技术常数。</p><p>统一标价是本课的菜单。若能对每个消费者要不同的价，MR 的逻辑要改，产量甚至可以回到有效；那是下一课价格歧视。本课禁止套利、禁止区别对待，只留一个 \\(P\\)。</p>',14)),(e(),i(s,null,{default:t(()=>[h(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMP%5B%22%E4%B8%8A%E8%8A%82%E8%AF%BE%EF%BC%9Ap%20%3D%20MC%22%5D%20--%3E%20DEM%5B%22%E9%9D%A2%E5%AF%B9%20P(Q)%22%5D%0A%20%20DEM%20--%3E%20MR%5B%22MR%20%3D%20MC%22%5D%0A%20%20MR%20--%3E%20LER%5B%22L%20%3D%20(P%E2%88%92MC)%2FP%20%3D%201%2F%7C%CE%B5%7C%22%5D%0A%20%20LER%20--%3E%20DWL%5B%22%E4%BA%A7%E9%87%8F%E4%BD%8E%E4%BA%8E%E7%AB%9E%E4%BA%89%E5%9F%BA%E5%87%86%22%5D%0A%20%20DWL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%8B%A5%E8%83%BD%E5%88%86%E5%BC%80%E8%A6%81%E4%BB%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>IRS 可以解释为什么只活得下一家，但勒纳公式对凸成本同样成立。结构来自市场边界与进入壁垒，不来自把平均成本画成下降就自动叫垄断。无谓损失是需求与 MC 之间的产量缺口，租金矩形是转移，二者不要加总成一个「坏处」。</p><p>进入壁垒在此当作结构给定：执照、专利、沉没的进入成本大到没人进。壁垒从哪来不展开；没有壁垒就回到上一课的长期零利润。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>加价的机制是需求斜率进入 MR：把价格微量降低以多卖一单位，必须用 \\(q P&#39;(q)\\) 计量已售部分的损失。弹性把斜率换成无量纲数字，于是不同市场的加价可以比较。无谓损失的机制是：在 \\(P\\gt \\mathrm{MC}\\) 的区间里，仍有人的边际评价高于边际成本，交易没做成。转移给垄断者的矩形是分配，三角形才是本课的效率缺口。</p><p>与短长期：垄断者也有既定规模与沉没。短期停产仍看 AVC；长期若不能阻止进入，\\(L\\) 会被进入削薄。本课把 \\(n=1\\) 钉死，是为了先把 \\(\\mathrm{MR}=\\mathrm{MC}\\) 写清楚。</p><p><span class="marginnote">不要把勒纳指数写成限价簿买卖价差。价差是微观结构的执行成本；这里是产品市场的 \\(P-\\mathrm{MC}\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多产品垄断、耐用品、动态限价，都会改 MR 的写法，本课不展开。自然垄断（次可加成本）提出的是「一家生产更省」与「加价扭曲」的冲突，规制是另一课序。也不用本课否定完全竞争基准：勒纳的零点正是上一课的 \\(P=\\mathrm{MC}\\)。</p><p>寡头把 MR 变成对对手行动的猜测，古诺课再写。勒纳用的是经济 MC，不是会计平均成本。也不把 \\(L\\) 写成买卖价差：微观结构的价差是库存与信息不对称，不是面对向下需求的加价。</p><p>后课默认：单一价格垄断满足 \\(\\mathrm{MR}=\\mathrm{MC}\\)，势力用勒纳指数读弹性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>面对向下需求时，一阶条件从 \\(P=\\mathrm{MC}\\) 换成 \\(\\mathrm{MR}=\\mathrm{MC}\\)。</li><li>勒纳指数等于需求弹性的倒数，测度加价不是会计利润率。</li><li>单一价格下产量低于竞争基准；无谓损失来自 \\(P\\gt \\mathrm{MC}\\) 的未成交。</li><li>下一课放开统一标价，看三级价格歧视如何改产量与剩余。</li><li>出处：Lerner, <em>RES</em>, 1934；Cournot, <em>Recherches</em>, 1838；Mas-Colell, Whinston and Green 第 12 章。</li></ul>',12))])}const B=n(d,[["render",c]]);export{u as __pageData,B as default};
